<script setup lang="ts">
const route=useRoute(), {api,add,money,message}=useMarketplace()
const {data:product,error,refresh}=await useAsyncData(`product-${route.params.slug}`,()=>api(`/api/products/${encodeURIComponent(String(route.params.slug))}`))
const added=ref(false)
useHead({title:()=>product.value?`${product.value.name} | پارتلی`:'کالا | پارتلی'})
</script>
<template><section class="shell py-12"><NuxtLink to="/catalog" class="mb-7 inline-block text-sm text-slate-500">فروشگاه / جزئیات کالا</NuxtLink><div v-if="error" class="market-error">{{message(error)}} <button class="underline" @click="refresh()">تلاش دوباره</button></div><div v-else-if="product" class="grid gap-8 lg:grid-cols-2"><div class="market-panel flex items-center justify-center bg-slate-100"><img :src="product.image" :alt="product.name" class="max-h-96 w-full object-contain"></div><div class="market-panel"><p class="market-eyebrow">{{product.category?.name}} · {{product.brand}}</p><h1 class="market-title">{{product.name}}</h1><p class="text-xs text-slate-400">کد کالا: {{product.sku}}</p><p class="mt-6 whitespace-pre-line text-sm leading-8 text-slate-600">{{product.description}}</p><div class="my-6 grid grid-cols-2 gap-3 border-y py-5 text-sm"><span>فروشنده</span><strong>{{product.vendor?.shopName || 'فروشگاه پارتلی'}}</strong><span>وضعیت کالا</span><strong>{{({NEW:'نو',USED:'کارکرده',REFURBISHED:'بازسازی‌شده'} as any)[product.condition]}}</strong><span>موجودی</span><strong>{{product.stock?`${product.stock} عدد`:'ناموجود'}}</strong></div><strong class="block text-2xl">{{money(product.price)}}</strong><button :disabled="!product.stock" class="market-primary mt-6 w-full" @click="add(product);added=true">{{product.stock?'افزودن به سبد خرید':'ناموجود'}}</button><p v-if="added" class="market-success mt-4" role="status">به سبد خرید اضافه شد. <NuxtLink to="/cart" class="underline">مشاهده سبد</NuxtLink></p><p class="mt-4 text-xs text-slate-500">پرداخت در محل · مبلغ نهایی در مرحله ثبت سفارش تأیید می‌شود.</p></div><div class="market-panel lg:col-span-2"><h2 class="mb-5 text-lg font-bold">سازگاری با خودرو</h2><ul v-if="product.fitments?.length" class="grid gap-3 text-sm sm:grid-cols-2"><li v-for="f in product.fitments" :key="f.variantId" class="rounded-xl bg-slate-50 p-4">{{f.variant.model.make.name}} / {{f.variant.model.name}} / {{f.variant.name}} <span class="text-slate-400">{{f.variant.years}}</span></li></ul><p v-else class="text-sm text-slate-500">اطلاعات سازگاری ثبت نشده است؛ پیش از سفارش از تطبیق مشخصات فنی اطمینان حاصل کنید.</p><dl v-if="product.specifications?.length" class="mt-6 grid gap-3 sm:grid-cols-2"><div v-for="s in product.specifications" :key="s.id" class="flex justify-between border-b py-3 text-sm"><dt>{{s.key || s.name}}</dt><dd>{{s.value}}</dd></div></dl></div></div></section></template>
